const item = $input.first().json;
const body = item.body || {};
const payload = body.payload || {};

const name = payload.recipient_name || 'Kak';
const resi = payload.tracking_number || '-';
const alamat = payload.address || '-';
const jadwal = payload.window || payload.scheduled_at || '-';
const ISSUE_LABEL = {
  kemasan_bocor: 'Kemasan bocor',
  kemasan_basah: 'Kemasan basah luar',
  suhu_naik: 'Suhu naik',
  pembeli_tidak_ada: 'Pembeli tidak di tempat',
  alamat_tidak_ditemukan: 'Alamat tidak ditemukan',
  cod_ditolak: 'COD ditolak'
};

const kendala = payload.issue_label || payload.message || ISSUE_LABEL[payload.issue_category] || payload.issue_category || 'Terjadi kendala operasional pada pengiriman paket.';
// Ringkasan harian mengirim angka; template tak boleh mencetak "undefined".
const angka = (value) => (value === null || value === undefined || value === '' ? '0' : String(value));
const catatan = payload.message ? 'Catatan: ' + payload.message : null;

const pembuka = 'Terima kasih telah memilih Anteraja Frozen \u2744\ufe0f';
// Notifikasi kurir dan admin adalah pesan operasional, bukan sapaan ke pembeli.
const pembukaInternal = 'Notifikasi operasional Anteraja Frozen \u2744\ufe0f';
const salam = 'Halo, Kak ' + name + '! \ud83d\udc4b';
const detail = ['\ud83d\udce6 Nomor Resi: ' + resi, '\ud83d\udccd Alamat Tujuan: ' + alamat].join('\n');

const decision = payload.decision || null;
const key = decision ? body.template + ':' + decision : body.template;
let text = null;

if (body.template === 'schedule_request') {
  text = [pembuka, '', salam, '', 'Kami ingin mengkonfirmasi jadwal penerimaan paket dengan detail berikut:', detail, '\ud83d\udd52 Estimasi Penerimaan: ' + jadwal, '', 'Mohon konfirmasi apakah Kakak bersedia menerima paket pada jadwal tersebut.', '', 'Balas *SIAP* untuk konfirmasi, atau *JADWAL LAIN* untuk meminta jadwal pengganti.'].join('\n');
} else if (body.template === 'schedule_rescheduled') {
  text = [pembuka, '', salam, '', 'Admin telah mengusulkan jadwal baru untuk penerimaan paket dengan detail berikut:', detail, '\ud83d\udd52 Jadwal Baru: ' + jadwal, '', '\u2744\ufe0f Penting untuk Diperhatikan \u26a0\ufe0f', 'Mohon pastikan paket dapat diterima pada jadwal tersebut agar kualitas dan kondisi produk tetap terjaga.', '', 'Balas *SIAP* untuk konfirmasi, atau *JADWAL LAIN* untuk meminta jadwal pengganti.'].join('\n');
} else if (body.template === 'delivery_pin') {
  text = [pembuka, '', salam, '', 'Kode PIN penerimaan paket ' + resi + ' adalah *' + (payload.pin || '-') + '*.', 'Tunjukkan kode ini kepada kurir saat paket diserahkan, ya, Kak. \u2744\ufe0f'].join('\n');
} else if (key === 'issue_decision_update:RETURN') {
  text = [pembuka, '', salam, '', 'Kami ingin menginformasikan bahwa terdapat kendala pada pengiriman paket Kakak dengan detail berikut:', detail, '\u26a0\ufe0f Kendala: ' + kendala, '', 'Berdasarkan kendala tersebut, paket Kakak akan dikembalikan kepada pengirim (return to sender).', catatan].filter(Boolean).join('\n');
} else if (key === 'issue_decision_update:RESEND') {
  // Informational: the replacement parcel has its own schedule request, which
  // is what asks the buyer for a window.
  text = [pembuka, '', salam, '', 'Kami ingin menginformasikan bahwa terdapat kendala pada pengiriman paket Kakak dengan detail berikut:', detail, '\u26a0\ufe0f Kendala: ' + kendala, '', 'Paket Kakak sedang kami proses untuk pengiriman ulang.', catatan].filter(Boolean).join('\n');
} else if (key === 'issue_decision_update:PROCEED') {
  text = [pembuka, '', salam, '', 'Kami ingin menginformasikan bahwa terdapat kendala pada pengiriman paket Kakak dengan detail berikut:', detail, '\u26a0\ufe0f Kendala: ' + kendala, '', 'Kami mohon maaf atas kendala yang terjadi. Sebagai bentuk tanggung jawab, kami menawarkan opsi untuk tetap melanjutkan pengiriman paket dan menerima bentuk kompensasi sesuai ketentuan layanan yang berlaku.', catatan].filter(Boolean).join('\n');
} else if (key === 'issue_decision_update:RECHECK') {
  text = [pembuka, '', salam, '', 'Kami ingin menginformasikan bahwa terdapat kendala pada pengiriman paket Kakak dengan detail berikut:', detail, '\u26a0\ufe0f Kendala: ' + kendala, '', 'Paket Kakak sedang diperiksa ulang oleh tim operasional. Kami akan mengabari perkembangannya.'].join('\n');
} else if (body.template === 'on_the_way') {
  text = [pembuka, '', salam, '', 'Paket ' + resi + ' sedang diantar oleh ' + (payload.courier_name || 'kurir kami') + '.', '\ud83d\udd52 Estimasi Penerimaan: ' + jadwal, '', 'Mohon pastikan ada penerima di lokasi ya, Kak. \u2744\ufe0f'].join('\n');
} else if (body.template === 'courier_arrived') {
  text = [pembuka, '', salam, '', 'Kurir kami sudah tiba di lokasi untuk paket ' + resi + '.', 'Mohon siapkan penerimaan paket beku agar kualitasnya tetap terjaga. \u2744\ufe0f'].join('\n');
} else if (body.template === 'delivered') {
  text = [pembuka, '', salam, '', 'Paket ' + resi + ' sudah diterima' + (payload.received_by ? ' oleh ' + payload.received_by : '') + '.', 'Terima kasih telah menggunakan Anteraja Frozen! \u2744\ufe0f'].join('\n');
} else if (body.template === 'reschedule_requested') {
  text = [
    pembukaInternal, '', salam, '',
    'Pembeli mengubah jadwal penerimaan paket ' + resi + ' lewat WhatsApp.',
    '\ud83d\udd52 Jadwal baru: ' + (payload.proposed_window || 'belum disebutkan'),
    payload.window ? '\ud83d\uddd3\ufe0f Jadwal sebelumnya: ' + payload.window : null,
    '',
    'Jadwal sudah diperbarui otomatis; silakan tugaskan kurir dari dashboard admin.'
  ].filter(Boolean).join('\n');
} else if (body.template === 'confirmation_overdue') {
  text = [
    pembukaInternal, '', salam, '',
    'Pembeli belum menjawab permintaan konfirmasi jadwal untuk paket ' + resi + '.',
    payload.age_minutes ? '\u23f3 Sudah menunggu sekitar ' + angka(payload.age_minutes) + ' menit.' : null,
    payload.window ? '\ud83d\udd52 Jadwal yang ditawarkan: ' + payload.window : null,
    '',
    'Mohon hubungi pembeli, atau jadwalkan ulang paket dari dashboard admin.'
  ].filter(Boolean).join('\n');
} else if (body.template === 'issue_reported') {
  text = [
    pembukaInternal, '', salam, '',
    'Kurir ' + (payload.courier_name || 'mitra kami') + ' melaporkan kendala pada paket ' + resi + '.',
    '\u26a0\ufe0f Kendala: ' + kendala,
    '',
    'Buka dashboard admin untuk memutuskan tindakannya (pengembalian, pengiriman ulang, atau lanjut).'
  ].join('\n');
} else if (body.template === 'task_rejected') {
  text = [
    pembukaInternal, '', salam, '',
    'Kurir ' + (payload.courier_name || 'mitra kami') + ' menolak penugasan untuk paket ' + resi + '.',
    '\ud83d\udcdd Alasan: ' + (payload.reason || 'tidak disebutkan'),
    payload.window ? '\ud83d\udd52 Jadwal paket: ' + payload.window : null,
    '',
    'Mohon tugaskan kurir lain dari dashboard admin.'
  ].filter(Boolean).join('\n');
} else if (body.template === 'resend_requested') {
  text = [
    pembukaInternal, '', salam, '',
    'Pembeli mengajukan pengiriman ulang untuk paket ' + resi + '.',
    payload.replacement_tracking_number ? '\ud83d\udce6 Resi pengganti: ' + payload.replacement_tracking_number : '\u23f3 Menunggu persetujuan admin.',
    '',
    'Periksa kelayakannya lalu proses pengiriman ulang dari dashboard admin.'
  ].join('\n');
} else if (body.template === 'daily_report') {
  text = [
    '\ud83d\udcca Laporan Harian Anteraja Frozen',
    '',
    salam,
    '\ud83d\uddd3\ufe0f Tanggal: ' + (payload.report_date || '-'),
    '',
    '\ud83d\udce6 Total paket: ' + angka(payload.total_shipments),
    '\u2705 Selesai (diterima): ' + angka(payload.delivered_count),
    '\ud83d\ude9a Dalam proses: ' + angka(payload.in_process_count),
    '\u26a0\ufe0f Kendala hari ini: ' + angka(payload.issue_count),
    '\u2696\ufe0f Keputusan admin: ' + angka(payload.decision_count),
    '\u23f3 Pembeli belum merespons: ' + angka(payload.unanswered_count),
    '',
    'Terima kasih telah menjaga rantai beku tetap terjaga \u2744\ufe0f'
  ].join('\n');
}

let phone = (payload.recipient_phone || '').replace(/[^0-9]/g, '');
if (phone.startsWith('0')) {
  phone = '62' + phone.slice(1);
}

if (!text) {
  return [{ json: { should_send: false, response: { delivered: false, reason: 'unmapped' } } }];
}

if (phone.length < 8) {
  return [{ json: { should_send: false, response: { delivered: false, reason: 'missing_recipient_phone' } } }];
}

return [{ json: {
  should_send: true,
  phone: phone,
  chat_id: phone + '@c.us',
  text: text,
  template: key,
  tracking_number: payload.tracking_number || null,
  client_token: payload.client_token || null,
  // Siapa penerimanya: balasan berikutnya dibaca sebagai aksi peran itu.
  recipient_type: payload.recipient_type || 'BUYER',
  context: {
    recipient_name: payload.recipient_name || null,
    window: payload.window || null,
    issue_label: payload.issue_label || null,
    decision: decision
  }
} }];

const item = $input.first().json || {};

// The WAHA failure is wrapped differently depending on how it failed, so flatten
// the whole item and look for the recipient problem anywhere in it.
let flat = '';
try { flat = JSON.stringify(item); } catch (error) { flat = String(item); }

const unreachable = /no lid|lid for user|not registered|invalid.*(number|wid)|not.*whatsapp/i.test(flat);

return [{ json: {
  delivered: false,
  reason: unreachable ? 'recipient_not_on_whatsapp' : 'send_failed',
  message: unreachable ? 'Nomor tujuan tidak terdaftar di WhatsApp.' : 'Pengiriman WhatsApp gagal.'
} }];
